CREATE FUNCTION public.validate_campaign_image_refs() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE ref text[]; prior text := ''; BEGIN IF auth.uid() IS NULL THEN RETURN NEW; END IF; IF TG_OP='UPDATE' THEN prior:=OLD.content; END IF; FOR ref IN SELECT regexp_matches(NEW.content,'\[cormyr-image:([a-zA-Z0-9_./-]+)\|','g') LOOP IF split_part(ref[1],'/',1)<>auth.uid()::text AND position('[cormyr-image:'||ref[1]||'|' in prior)=0 THEN RAISE EXCEPTION 'Imagem pertence a outro autor; envie sua própria imagem'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_record_images BEFORE INSERT OR UPDATE ON public.campaign_records FOR EACH ROW EXECUTE FUNCTION public.validate_campaign_image_refs();
CREATE TRIGGER validate_letter_images BEFORE INSERT OR UPDATE ON public.campaign_letters FOR EACH ROW EXECUTE FUNCTION public.validate_campaign_image_refs();
CREATE TRIGGER validate_reply_images BEFORE INSERT OR UPDATE ON public.letter_replies FOR EACH ROW EXECUTE FUNCTION public.validate_campaign_image_refs();